"""Exact original-ID bindings for a complete chain ending in a free approach.

The semantic planner qualifies the original chains first; the shared native
registry independently proves ownership before GN qualifies their geometry.
No coordinates are read and neither original Street directions nor IDs change.
"""
from numbers import Integral

from .curved_separator_chain_bindings import _rows, _unique
from .curved_separator_member_bindings import member_chains, permission_rows


COLUMNS = {
    'Mapping': ('st_ps_street_id', 'st_ps_first_section', 'st_ps_last_section',
                'st_ps_start_role', 'st_ps_end_role'),
    'Corridors': ('st_cs_span_index', 'st_cs_street_id', 'st_cs_start_index', 'st_cs_end_index'),
    'External Approaches': ('st_ca_span_index', 'st_ca_street_id', 'st_ca_start_index',
                            'st_ca_end_role', 'st_ca_owner_id', 'st_ca_next_section_id'),
    'Approaches': ('st_cj_street_id', 'st_cj_section_id', 'st_cj_reverse', 'st_cj_junction_id'),
}


def resolve(item, columns, owners, *, longitudinal_chains=False):
    """Resolve a semantic free chain to exact native route/port/owner indices."""
    tables = {name: _rows(columns[name], fields) for name, fields in COLUMNS.items()}
    mapping, corridors, external, mouths = (tables[name] for name in COLUMNS)
    spans = _unique((r[:3] for r in mapping), 'original span')
    ports = _unique((r[:3] for r in mouths), 'original endpoint')
    corridor_by_span = _unique((r[0] for r in corridors), 'corridor span')
    external_by_span = _unique((r[0] for r in external), 'external approach span')
    if set(corridor_by_span).intersection(external_by_span):
        raise ValueError('An original span cannot have two generated route owners')
    if type(item.attached_at_head) is not bool:
        raise ValueError('Free chain needs an explicit attached Bundle end')
    if any(len(rows) != 2 for rows in (item.member_street_ids, item.member_span_ids,
                                       item.intermediate_sites, item.head_ends, item.tail_ends)):
        raise ValueError('Free chain binding requires two complete original members')
    if len(set(item.member_street_ids)) != 2:
        raise ValueError('Free chain members must have distinct original IDs')
    chains = member_chains(item, longitudinal_chains=longitudinal_chains)
    attached_sites = item.head_sites if item.attached_at_head else item.tail_sites
    free_sites = item.tail_sites if item.attached_at_head else item.head_sites
    attached_ends = item.head_ends if item.attached_at_head else item.tail_ends
    free_ends = item.tail_ends if item.attached_at_head else item.head_ends
    if not attached_sites or free_sites or attached_sites not in owners:
        raise ValueError('Free chain needs one exact attached owner and one genuinely free Bundle end')
    if len(set(owners.values())) != len(owners):
        raise ValueError('Distinct original owner groups cannot alias a native patch')
    groups = {}
    for sites, value in owners.items():
        if not sites or isinstance(value, bool) or not isinstance(value, Integral) or not 0 <= value < 2**20:
            raise ValueError('Native surface owner indices must be bounded integers')
        for site in sites:
            if site in groups:
                raise ValueError('Original junction has several generated owners')
            groups[site] = sites
    all_middle = [sites for rows in item.intermediate_sites for sites in rows]
    if (not all_middle or len(all_middle) != len(set(all_middle)) or attached_sites in all_middle or
            any(sites not in owners for sites in all_middle)):
        raise ValueError('Free chain needs distinct, exact intermediate owners outside its attached cap')
    record = dict(bundle_id=item.bundle_id, kind=3, member_a=attached_ends[0].street_id,
                  member_b=attached_ends[1].street_id, attached_patch=owners[attached_sites])
    rules = []
    for side, chain in enumerate(chains):
        identities = item.member_span_ids[side]
        middle = item.intermediate_sites[side]
        # Traverse from the attached cap to the free end. Only traversal order
        # changes here; the authored mapping and endpoint directions stay exact.
        if not item.attached_at_head:
            identities, middle = identities[::-1], middle[::-1]
        if not identities or len(set(identities)) != len(identities) or len(middle) != len(identities)-1:
            raise ValueError('Complete member routes require exactly one owner at each join')
        selected = []
        for ordinal, identity in enumerate(identities):
            sid = identity[0]
            if identity not in spans:
                raise ValueError('Free chain lost an original span identity')
            span = spans[identity]
            if ordinal < len(identities)-1:
                if span not in corridor_by_span:
                    raise ValueError('Only the terminal route may be a free approach')
                row = corridor_by_span[span]; actual = corridors[row]
                if actual[1] != sid or any(not 0 <= port < len(mouths) for port in actual[2:]):
                    raise ValueError('Corridor registry lost its Street or original ports')
                if (mouths[actual[2]][:3] != (sid, identity[1], 0) or
                        mouths[actual[3]][:3] != (sid, identity[2], 1) or mapping[span][3:] != (0, 0)):
                    raise ValueError('Corridor endpoints differ from the original Section ends')
                selected.append((1, row, actual[2:]))
            else:
                if span not in external_by_span:
                    raise ValueError('Free chain must terminate in its original external approach')
                row = external_by_span[span]; actual = external[row]; port = actual[2]
                if (actual[1] != sid or not 0 <= port < len(mouths) or actual[3:] != (1, -1, -1)):
                    raise ValueError('Terminal approach must end freely without a category or remote owner')
                reverse = mouths[port][2]
                if reverse not in (0, 1) or mouths[port][:3] != (sid, identity[2] if reverse else identity[1], reverse):
                    raise ValueError('Free approach lost its exact attached Section endpoint')
                end = free_ends[side]
                expected = (sid, identity[1] if reverse else identity[2], 1-reverse)
                if (end.street_id, end.section_id, end.end) != expected or expected in ports:
                    raise ValueError('Free terminal identity must be exact and have no generated port')
                if mapping[span][3:] != ((1, 0) if reverse else (0, 1)):
                    raise ValueError('Original mapping does not declare this terminal free')
                selected.append((3, row, (port,)))
        expected = {(1, i) for i, r in enumerate(corridors) if r[1] in chain}
        expected |= {(3, i) for i, r in enumerate(external) if r[1] in chain}
        if {(kind, row) for kind, row, _ in selected} != expected:
            raise ValueError('Free chain must cover every generated member route exactly')
        endpoint = attached_ends[side]
        key = (endpoint.street_id, endpoint.section_id, endpoint.end)
        if key not in ports or key[0] != identities[0][0] or groups.get(mouths[ports[key]][3]) != attached_sites:
            raise ValueError('Free chain lost its exact attached terminal')
        entry = ports[key]
        record[('a_' if side == 0 else 'b_')+'attached'] = entry
        for ordinal, (kind, row, pair) in enumerate(selected):
            if entry not in pair:
                raise ValueError('Member chain is disconnected or out of order')
            rules.append((side, kind, row))
            if kind == 3:
                record[('a_' if side == 0 else 'b_')+'external'] = row
                continue
            leave = pair[1] if entry == pair[0] else pair[0]
            junction = mouths[leave][3]
            if groups.get(junction) != middle[ordinal]:
                raise ValueError('Member join differs from its original intermediate owner')
            following = [p for p in selected[ordinal+1][2] if mouths[p][3] == junction]
            if len(following) != 1:
                raise ValueError('Member routes must meet at the exact original junction')
            rules.append((side, 0, owners[middle[ordinal]])); entry = following[0]
    rules.append((2, 0, record['attached_patch']))
    if len(rules) != len(set(rules)) or len(rules) > 512:
        raise ValueError('Free chain owner permissions must be unique and bounded')
    if record['a_attached'] == record['b_attached'] or record['a_external'] == record['b_external']:
        raise ValueError('Free chain members cannot share terminal ports or approaches')
    return record, tuple(rules)


def bind(items, tables, label, *, longitudinal_chains=False):
    from types import SimpleNamespace
    from .curved_junction_bindings import _mesh
    from .curved_patch_provider_bindings import owner_sites, values
    sites = values(tables['Junctions'], 'st_cj_junction_id')
    owners = {tuple(sorted(sites[i] for i in group)): owner for owner, group in
              owner_sites({key: SimpleNamespace(data=value) for key, value in tables.items()}).items()}
    columns = {key: {name: values(tables[key], name) for name in fields} for key, fields in COLUMNS.items()}
    rows, rules = [], []
    for item in items:
        row, allowed = resolve(item, columns, owners, longitudinal_chains=longitudinal_chains); rows.append(row)
        rules.extend(permission_rows(item.bundle_id, allowed, columns, longitudinal_chains=longitudinal_chains))
    if len(rows) != len({row['bundle_id'] for row in rows}):
        raise ValueError('Duplicate free chain declaration')
    declarations = _mesh(label+' private free chains', [(0., 0., 0.)]*len(rows), [], [
        ('st_sb_'+key, 'INT', 'POINT', [row[key] for row in rows]) for key in
        ('bundle_id', 'kind', 'member_a', 'member_b', 'attached_patch',
         'a_attached', 'b_attached', 'a_external', 'b_external')])
    permissions = _mesh(label+' private free chain owners', [(0., 0., 0.)]*len(rules), [], [
        ('st_sr_'+key, 'INT', 'POINT', [row[key] for row in rules])
        for key in ('bundle_id', 'role', 'kind', 'owner')+(('street_id',) if longitudinal_chains else ())])
    return declarations, permissions


def bind_mixed(preparation, tables, label, *, longitudinal_chains=False):
    """Append free chains while preserving every existing declaration column."""
    import bpy
    from types import SimpleNamespace
    from .curved_separator_chain_bindings import bind_mixed as existing
    from .curved_junction_bindings import _mesh
    from .curved_patch_provider_bindings import values
    previous = SimpleNamespace(closed=preparation.closed, free_ended=preparation.free_ended,
                               chained=preparation.chained, selection_ended=getattr(preparation, 'selection_ended', ()))
    base, old_rules = existing(previous, tables, label, longitudinal_chains=longitudinal_chains)
    temporary = [base, old_rules]
    try:
        free, free_rules = bind(getattr(preparation, 'free_chained', ()), tables, label, longitudinal_chains=longitudinal_chains)
        temporary.extend((free, free_rules))
        names = tuple(a.name for a in base.attributes if a.name.startswith('st_sb_'))+('st_sb_a_external','st_sb_b_external')
        aliases = {'st_sb_head_patch':'st_sb_attached_patch',
                   'st_sb_a_head':'st_sb_a_attached', 'st_sb_b_head':'st_sb_b_attached'}
        columns = {}
        for key in names:
            source = aliases.get(key, key)
            columns[key] = (values(base, key) if key in base.attributes else [-1]*len(base.vertices)) + (
                values(free, source) if source in free.attributes else [-1]*len(free.vertices))
        ids = columns['st_sb_bundle_id']
        if len(ids) != len(set(ids)):
            raise ValueError('A Bundle cannot have several separator declaration kinds')
        rule_columns = {key:values(old_rules,key)+values(free_rules,key) for key in
                        ('st_sr_bundle_id','st_sr_role','st_sr_kind','st_sr_owner')+
                        (('st_sr_street_id',) if longitudinal_chains else ())}
        declarations = _mesh(label+' private separators',[(0.,0.,0.)]*len(ids),[],[
            (key,'INT','POINT',column) for key,column in columns.items()])
        permissions = _mesh(label+' private separator side owners',[(0.,0.,0.)]*len(rule_columns['st_sr_bundle_id']),[],[
            (key,'INT','POINT',column) for key,column in rule_columns.items()])
        return declarations, permissions
    finally:
        for mesh in temporary:
            if mesh.users == 0: bpy.data.meshes.remove(mesh)
